<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class LibraryController extends Controller{
 private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('librarian')||$r->user()->canDo('library.manage'),403);}
 public function index(Request $r){$q=DB::table('library_books as b')->leftJoin('library_copies as c','c.library_book_id','=','b.id')->groupBy('b.id','b.isbn','b.title','b.authors','b.publisher','b.publication_year')->select('b.id','b.isbn','b.title','b.authors','b.publisher','b.publication_year',DB::raw('count(c.id) copies'),DB::raw("sum(case when c.status='available' then 1 else 0 end) available"));if($r->filled('q')){$s='%'.$r->q.'%';$q->where(fn($x)=>$x->where('b.title','like',$s)->orWhere('b.authors','like',$s)->orWhere('b.isbn','like',$s));}$books=$q->orderBy('b.title')->limit(200)->get();$overdue=DB::table('library_loans')->whereNull('returned_at')->where('due_on','<',today())->count();return view('library.index',compact('books','overdue'));}
 public function store(Request $r){$this->manage($r);$d=$r->validate(['isbn'=>'nullable|string|max:30','title'=>'required|string|max:500','authors'=>'nullable|string|max:500','publisher'=>'nullable|string|max:255','publication_year'=>'nullable|integer|min:1000|max:2100','bbk'=>'nullable|string|max:100','udc'=>'nullable|string|max:100']);$id=DB::table('library_books')->insertGetId($d+['created_at'=>now(),'updated_at'=>now()]);return redirect()->route('library.show',$id);}
 public function show(Request $r,$id){$book=DB::table('library_books')->find($id);abort_if(!$book,404);$copies=DB::table('library_copies')->where('library_book_id',$id)->orderBy('inventory_number')->get();$links=DB::table('library_subject_books as l')->join('subjects as s','s.id','=','l.subject_id')->leftJoin('study_groups as g','g.id','=','l.study_group_id')->where('l.library_book_id',$id)->select('l.*','s.name as subject_name','g.name as group_name')->get();$subjects=DB::table('subjects')->orderBy('name')->get();$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();return view('library.show',compact('book','copies','links','subjects','groups'));}
 public function copy(Request $r,$id){$this->manage($r);$d=$r->validate(['inventory_number'=>'required|string|max:100|unique:library_copies,inventory_number','barcode'=>'nullable|string|max:100|unique:library_copies,barcode','location'=>'nullable|string|max:255','condition'=>'required|in:new,good,worn,damaged','acquired_on'=>'nullable|date','price'=>'nullable|numeric|min:0']);DB::table('library_copies')->insert($d+['library_book_id'=>$id,'status'=>'available','created_at'=>now(),'updated_at'=>now()]);return back();}
 public function link(Request $r,$id){$this->manage($r);$d=$r->validate(['subject_id'=>'required|exists:subjects,id','study_group_id'=>'nullable|exists:study_groups,id','recommended_copies'=>'nullable|integer|min:0','required'=>'nullable|boolean']);DB::table('library_subject_books')->updateOrInsert(['library_book_id'=>$id,'subject_id'=>$d['subject_id'],'study_group_id'=>$d['study_group_id']??null],['recommended_copies'=>$d['recommended_copies']??null,'required'=>(bool)($d['required']??false),'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function desk(Request $r){$this->manage($r);$active=DB::table('library_loans as l')->join('library_copies as c','c.id','=','l.library_copy_id')->join('library_books as b','b.id','=','c.library_book_id')->leftJoin('students as s','s.id','=','l.student_id')->leftJoin('teachers as t','t.id','=','l.teacher_id')->whereNull('l.returned_at')->select('l.*','c.inventory_number','c.barcode','b.title','s.last_name as student_last','s.first_name as student_first','t.last_name as teacher_last','t.first_name as teacher_first')->orderBy('l.due_on')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('library.desk',compact('active','students','teachers'));}
 public function issue(Request $r){$this->manage($r);$d=$r->validate(['code'=>'required|string|max:100','reader_type'=>'required|in:student,teacher','student_id'=>'nullable|exists:students,id','teacher_id'=>'nullable|exists:teachers,id','due_on'=>'required|date|after_or_equal:today','note'=>'nullable|string|max:2000']);$copy=DB::table('library_copies')->where(fn($q)=>$q->where('barcode',$d['code'])->orWhere('inventory_number',$d['code']))->first();abort_if(!$copy,404,'Экземпляр не найден.');abort_unless($copy->status==='available',422,'Экземпляр уже выдан или недоступен.');$sid=$d['reader_type']==='student'?($d['student_id']??null):null;$tid=$d['reader_type']==='teacher'?($d['teacher_id']??null):null;abort_if(!$sid&&!$tid,422,'Выберите читателя.');DB::transaction(function()use($copy,$sid,$tid,$d,$r){DB::table('library_loans')->insert(['library_copy_id'=>$copy->id,'student_id'=>$sid,'teacher_id'=>$tid,'issued_by'=>$r->user()->id,'issued_at'=>now(),'due_on'=>$d['due_on'],'note'=>$d['note']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('library_copies')->where('id',$copy->id)->update(['status'=>'loaned','updated_at'=>now()]);});return back()->with('success','Книга выдана.');}
 public function returnBook(Request $r,$loan){$this->manage($r);$x=DB::table('library_loans')->whereNull('returned_at')->find($loan);abort_if(!$x,404);DB::transaction(function()use($x,$r){DB::table('library_loans')->where('id',$x->id)->update(['returned_at'=>now(),'returned_by'=>$r->user()->id,'updated_at'=>now()]);DB::table('library_copies')->where('id',$x->library_copy_id)->update(['status'=>'available','updated_at'=>now()]);});return back()->with('success','Возврат зарегистрирован.');}
 public function my(Request $r){abort_unless($r->user()->student_id||$r->user()->teacher_id,403);$q=DB::table('library_loans as l')->join('library_copies as c','c.id','=','l.library_copy_id')->join('library_books as b','b.id','=','c.library_book_id')->select('l.*','b.title','b.authors','c.inventory_number');$r->user()->student_id?$q->where('l.student_id',$r->user()->student_id):$q->where('l.teacher_id',$r->user()->teacher_id);$loans=$q->orderByDesc('l.issued_at')->get();return view('library.my',compact('loans'));}
}